  1	<?php
  2	
  3	namespace Modules\AI\Domain\Decision;
  4	
  5	use Modules\AI\Domain\Doctrine\ArchetypeDoctrine;
  6	use Modules\AI\Domain\Persona\SavingsGoal;
  7	use Modules\AI\Enums\AiStockpileStrategy;
  8	use Modules\AI\Models\AiProfile;
  9	use OGame\Factories\PlayerServiceFactory;
 10	use OGame\GameObjects\Models\Enums\GameObjectType;
 11	use OGame\Models\Resources;
 12	use OGame\Models\User;
 13	use OGame\Services\BuildingQueueService;
 14	use OGame\Services\ObjectService;
 15	use OGame\Services\PlanetService;
 16	use OGame\Services\PlayerService;
 17	use OGame\Services\ResearchQueueService;
 18	
 19	/**
 20	 * Answers one question about the account's own economy: is there a building or a technology it can
 21	 * legally queue now, and on which planet?
 22	 *
 23	 * Two things want a building. The chain wants the facility a later capability cannot exist without
 24	 * -- an account with no research lab can never research, and one with no shipyard can never own a
 25	 * ship -- and the economy wants the upgrade that repays itself fastest, or the storage that is about
 26	 * to overflow. The plan runs in two passes across the account's planets: first a warehouse that is
 27	 * about to overflow anywhere (it stops that planet producing, so it outranks every routine step on
 28	 * every other planet), then the routine economy planet by planet -- the energy a planet needs before
 29	 * it throttles, the chain's facilities, then the fastest-paying mine. The cross-planet storage pass
 30	 * is what keeps a full warehouse on one colony from waiting behind a routine mine on the homeworld.
 31	 *
 32	 * Both are only suggestions. Every gate is the host's own -- planet type, free queue space,
 33	 * requirements met against what is built *and* queued, and a price the planet can pay, which is the
 34	 * same set the building page shows a human -- so the module never restates an OGame rule. A target
 35	 * the host rejects is not an error but a fall-through: the planner tries the next one, which is what
 36	 * keeps a single impossible favourite from costing the account its whole build capability.
 37	 *
 38	 * Affordability is a real gate rather than a nicety: `BuildingQueueService::start()` cancels a queue
 39	 * item it cannot pay for, so publishing `build` while short of resources spends a queue slot and
 40	 * reports nothing at all.
 41	 */
 42	class QueueableBuildingPlanner
 43	{
 44	    /** The lab is one queue for the account, so its step has one slot beside the per-planet building steps. */
 45	    private const LAB_STEP = 'lab';
 46	
 47	    /** The pass that stands the facilities a bare planet's wall waits on: it is a fix, not a choice. */
 48	    private const WALL_STEP = 'wall';
 49	
 50	    public function __construct(
 51	        private PlayerServiceFactory $playerServiceFactory,
 52	        private FacilityChain $facilityChain,
 53	        private EnergyCapacity $energyCapacity,
 54	        private EconomyUpgrades $economyUpgrades,
 55	        private ReserveFloor $reserveFloor,
 56	        private BuildingQueueService $buildingQueueService,
 57	        private ResearchQueueService $researchQueueService,
 58	    ) {
 59	    }
 60	
 61	    public function plan(int $playerId, ?PlayerService $player = null): QueueableBuilding|QueueableResearch|null
 62	    {
 63	        return $this->steps($playerId, $player, 1)[0] ?? null;
 64	    }
 65	
 66	    /**
 67	     * Every queue a player would fill in one login: at most one building per planet, because each planet
 68	     * pays from its own stock and has its own build queue, and at most one technology, because the
 69	     * lab is one queue for the account. The order is plan()'s, so the first step is the one plan()
 70	     * returns.
 71	     *
 72	     * @return list<QueueableBuilding|QueueableResearch>
 73	     */
 74	    public function steps(int $playerId, ?PlayerService $player = null, int $limit = PHP_INT_MAX): array
 75	    {
 76	        // An account the module does not manage has no policy to apply, so it gets no capability.
 77	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
 78	        if ($profile === null) {
 79	            return [];
 80	        }
 81	
 82	        // The module owns profile rows; the host owns accounts. A profile can outlive its account or
 83	        // be written by a fixture, and loading an account the host does not have throws -- so the
 84	        // precondition is asked here rather than discovered in the host service.
 85	        if (!User::query()->whereKey($playerId)->exists()) {
 86	            return [];
 87	        }
 88	
 89	        // Refresh every planet's live balance once: the candidate pass reads stored amounts and
 90	        // energy, and a balance read stale is exactly the balance the queue later cancels on. The
 91	        // refresh stays in memory -- the observation path must not write.
 92	        $planets = ($player ?? $this->playerServiceFactory->make($playerId, true))->planets->all();
 93	        foreach ($planets as $planet) {
 94	            $planet->updateResources(false);
 95	            $planet->updateResourceProductionStats(false);
 96	            $planet->updateResourceStorageStats(false);
 97	        }
 98	
 99	        $passes = $this->passes($profile);
100	
101	        // What every planet is holding back, once per session: reading it walks the same candidate
102	        // lists the passes do, so asking again inside each pass would repeat a planet's whole economy,
103	        // and a planet's hold is its own.
104	        // It is also what keeps this list honest: the cohort reads "buildable" from exactly these
105	        // steps, so a planet whose pile the goal reserves must not be offered here -- otherwise the
106	        // read-out says buildable while the account rightly saves, and the invariant flags a saver
107	        // for behaving as designed.
108	        $goals = [];
109	        foreach ($planets as $planet) {
110	            $goals[$planet->getPlanetId()] = $this->savingsGoal($planet, $profile);
111	        }
112	
113	        $steps = [];
114	        foreach ($passes as $pass => $candidates) {
115	            foreach ($planets as $planet) {
116	                if (count($steps) >= $limit) {
117	                    return array_values($steps);
118	                }
119	
120	                $steps = $this->withStep($steps, $planet, $profile, $candidates, $goals[$planet->getPlanetId()], $pass === self::WALL_STEP);
121	            }
122	        }
123	
124	        return array_values($steps);
125	    }
126	
127	    /**
128	     * The candidate lists in the order the planner tries them. A warehouse about to overflow stops
129	     * that planet producing, so its pass runs across every planet before any routine step; a full
130	     * warehouse (E7) is a spend signal and comes next; then the routine economy: energy before it
131	     * throttles, the chain's facilities, the fastest-paying mine. Public so a read-out explains a
132	     * planet with the same lists the decision used.
133	     *
134	     * @return array<string, callable(PlanetService): list<BuildCandidate>>
135	     */
136	    public function passes(AiProfile $profile): array
137	    {
138	        return [
139	            // A planet holding no defence while a sibling already stands a wall is past the
140	            // account's opening with a sibling walled everywhere else: the facilities the wall
141	            // itself waits on come before the economy, so the planet is not left naked behind a
142	            // stock it is busy spending (QUAL-003). The step is the same shape as a wall order: a
143	            // saving the economy is holding back does not veto it, because a planet with no wall is
144	            // the state the account is fixing, not a step it chooses between (QUAL-003).
145	            'wall' => fn (PlanetService $planet): array => $this->facilityChain->wallPending($planet),
146	            // The archetype's written opening and research path (architecture step 4): the build list a guide
147	            // gives, in order, before the payback rules below take over. An object the host lacks is skipped.
148	            'doctrine' => fn (PlanetService $planet): array => [
149	                ...app(ArchetypeDoctrine::class)->openingStep($profile->archetype, $planet),
150	                ...($planet->getPlayer() !== null ? app(ArchetypeDoctrine::class)->researchStep($profile->archetype, $planet->getPlayer()) : []),
151	            ],
152	            'storage' => fn (PlanetService $planet): array => $this->economyUpgrades->storage($planet, $profile),
153	            'surplus' => fn (PlanetService $planet): array => $this->economyUpgrades->spendSurplus($planet, $profile),
154	            'routine' => fn (PlanetService $planet): array => [
155	                ...$this->energyCapacity->pending($planet),
156	                ...$this->facilityChain->pending($planet),
157	                ...$this->economyUpgrades->storageForPrice($planet, $profile),
158	                ...$this->economyUpgrades->production($planet, $profile),
159	            ],
160	            // A planet sitting on six times the price of a facility it does not own buys it -- but only
161	            // once nothing urgent is left, which is what that pass says it is for: the capacity the host
162	            // throttles the planet without, the prerequisites the rest of the game is gated behind and the
163	            // mine that repays first all outrank a facility bought for its own sake (COVER-*). Placed
164	            // ahead of them it bought a robotics factory on a planet that could not yet cover its mines
165	            // (measured: AiCapabilityPublicationTest, EnergyCapacityTest).
166	            'ambition' => fn (PlanetService $planet): array => $this->economyUpgrades->ambitions($planet),
167	        ];
168	    }
169	
170	    /**
171	     * The build queue and the lab run side by side, so a planet's building and the account's one
172	     * technology are separate steps: a planet whose best candidate is a technology still builds.
173	     *
174	     * @param array<int|string, QueueableBuilding|QueueableResearch> $steps
175	     * @param callable(PlanetService): list<BuildCandidate> $pass
176	     * @return array<int|string, QueueableBuilding|QueueableResearch>
177	     */
178	    private function withStep(array $steps, PlanetService $planet, AiProfile $profile, callable $pass, ?SavingsGoal $goal, bool $wall = false): array
179	    {
180	        $candidates = $pass($planet);
181	        $isResearch = static fn (BuildCandidate $candidate): bool => ObjectService::getObjectById($candidate->buildingId)->type === GameObjectType::Research;
182	
183	        // The candidate list is in priority order, so whichever queue its first entry belongs to is tried first.
184	        $queues = [$planet->getPlanetId() => false, self::LAB_STEP => true];
185	        if ($candidates !== [] && $isResearch($candidates[0])) {
186	            $queues = array_reverse($queues, true);
187	        }
188	
189	        foreach ($queues as $key => $research) {
190	            if (isset($steps[$key])) {
191	                continue;
192	            }
193	
194	            $step = $this->firstQueueable($planet, $profile, array_values(array_filter($candidates, static fn (BuildCandidate $candidate): bool => $isResearch($candidate) === $research)), $wall ? null : $goal);
195	            if ($step !== null) {
196	                $steps[$key] = $step;
197	            }
198	        }
199	
200	        return $steps;
201	    }
202	
203	    /**
204	     * The first candidate this planet can actually queue, or null when none of them is legal.
205	     *
206	     * @param list<BuildCandidate> $candidates
207	     */
208	    private function firstQueueable(PlanetService $planet, AiProfile $profile, array $candidates, ?SavingsGoal $goal): QueueableBuilding|QueueableResearch|null
209	    {
210	        foreach ($candidates as $candidate) {
211	            if (!$this->canSpendFor($planet, $goal, $candidate)) {
212	                continue;
213	            }
214	
215	            // Which queue takes a step is the host's object type, not this module's opinion: the
216	            // chain hands over prerequisites, and a technology among them is research.
217	            if (ObjectService::getObjectById($candidate->buildingId)->type === GameObjectType::Research) {
218	                $research = $this->queueableResearch($planet, $candidate);
219	                if ($research === null) {
220	                    continue;
221	                }
222	
223	                return $research;
224	            }
225	
226	            $planetId = $planet->getPlanetId();
227	            if (!$this->canQueue($planet, $candidate)) {
228	                continue;
229	            }
230	
231	            return app()->makeWith(QueueableBuilding::class, [
232	                'planetId' => $planetId,
233	                'buildingId' => $candidate->buildingId,
234	                'reason' => $candidate->reason,
235	            ]);
236	        }
237	
238	        return null;
239	    }
240	
241	    /**
242	     * Whether the building queue will take this candidate on this planet right now.
243	     *
244	     * Public because "the building queue cannot answer this" is a question a second planner has to
245	     * ask: a planet that cannot buy capacity here has one other route, and the yard may only take it
246	     * when this says no. The gate itself stays in one place rather than being restated next to it.
247	     */
248	    public function canQueue(PlanetService $planet, BuildCandidate $candidate): bool
249	    {
250	        return $this->refusal($planet, $candidate) === null;
251	    }
252	
253	    /**
254	     * Whether an order planned earlier can no longer be placed because the queue moved on since: the
255	     * planet's queue filled, or the station's units went into production. The executor asks this for
256	     * an order carrying its own binding, so a stale order is planned again from the live state
257	     * instead of being sent to a host gate that refuses it (STUCK: "Maximum number of items already
258	     * in queue" and shipyard_busy, repeated by the same accounts).
259	     */
260	    public function orderIsStale(int $playerId, int $planetId, int $buildingId): bool
261	    {
262	        $player = $this->playerServiceFactory->make($playerId, true);
263	        $planet = $player->planets->all()[$planetId] ?? null;
264	
265	        if ($planet === null) {
266	            foreach ($player->planets->all() as $candidate) {
267	                if ($candidate->getPlanetId() === $planetId) {
268	                    $planet = $candidate;
269	                    break;
270	                }
271	            }
272	        }
273	
274	        if ($planet === null) {
275	            return false;
276	        }
277	
278	        return $this->buildingQueueService->retrieveQueue($planet)->isQueueFull()
279	            || $player->isObjectUpgradeBlocked($buildingId);
280	    }
281	
282	    /**
283	     * Which of the host's gates refuses this building here, or null when the planet can queue it.
284	     * The gates are asked in the order the building page asks them: planet type, free queue space,
285	     * met requirements, a balance it can pay and a field the building still fits in. Named, so a
286	     * planet that never builds says why instead of reading as idle.
287	     */
288	    public function refusal(PlanetService $planet, BuildCandidate $candidate): ?string
289	    {
290	        $object = ObjectService::getObjectById($candidate->buildingId);
291	        $machineName = $object->machine_name;
292	
293	        if (!ObjectService::objectValidPlanetType($machineName, $planet)) {
294	            return 'planet type';
295	        }
296	        if ($this->buildingQueueService->retrieveQueue($planet)->isQueueFull()) {
297	            return 'queue full';
298	        }
299	        // The host refuses an order for a station whose units are already in production, and the
300	        // executor asks the same gate (`QueueAiBuildingAction`). Not asked here, the pass offers a
301	        // step the executor then refuses: the planet spends its one step on a refusal, queues
302	        // nothing, and still reads buildable to the planner -- idle while called buildable (live:
303	        // player 44, 4 of 4 planets). Asking it here lets the planet fall through to its next
304	        // candidate instead.
305	        if ($planet->getPlayer()?->isObjectUpgradeBlocked($candidate->buildingId) === true) {
306	            return 'shipyard busy';
307	        }
308	        if (!ObjectService::objectRequirementsMetWithQueue($machineName, $planet->getObjectLevel($machineName) + 1, $planet)) {
309	            return 'requirements';
310	        }
311	        if (!$planet->hasResources($this->withReserve($planet, ObjectService::getObjectPrice($machineName, $planet), ReserveFloor::ECONOMY_HOURS))) {
312	            return 'price plus reserve';
313	        }
314	        // `BuildingQueueService::start()` refuses a field-consuming building once the planet's fields
315	        // are used up, and a terraformer cannot rescue it because a terraformer consumes a field too.
316	        if ($object->consumesPlanetField && $planet->getBuildingCount() >= $planet->getPlanetFieldMax()) {
317	            return 'no free field';
318	        }
319	
320	        return null;
321	    }
322	
323	    /**
324	     * What this planet is saving for: the price plus reserve of the first economy step the planet is
325	     * short of, or null when it is not saving. A player mines while short, so anything else that spends
326	     * the same resource waits (the shipyard leaves the balance alone until the step is paid).
327	     */
328	    public function savingFor(PlanetService $planet, AiProfile $profile): ?Resources
329	    {
330	        $candidate = $this->savingCandidate($planet, $profile);
331	        if ($candidate === null) {
332	            return null;
333	        }
334	
335	        return $this->withReserve($planet, ObjectService::getObjectPrice(ObjectService::getObjectById($candidate->buildingId)->machine_name, $planet), ReserveFloor::ECONOMY_HOURS);
336	    }
337	
338	    /** The first step in the planner's own order this planet cannot yet pay for, or null when it can pay for all of them. */
339	    private function savingCandidate(PlanetService $planet, AiProfile $profile): ?BuildCandidate
340	    {
341	        foreach ($this->passes($profile) as $pass) {
342	            foreach ($pass($planet) as $candidate) {
343	                if ($this->refusal($planet, $candidate) === 'price plus reserve') {
344	                    return $candidate;
345	                }
346	            }
347	        }
348	
349	        return null;
350	    }
351	
352	    /**
353	     * What this planet is holding resources back for, or null when it spends freely.
354	     *
355	     * Only a goal saver holds anything back (PERS-007). The strategy decides how the pile is spent, never
356	     * whether the account spends at all: every other strategy leaves the balance alone, so the decision
357	     * doctrine's spend-first rule stands for the immediate spender. The goal is the first step the planet
358	     * cannot yet pay for -- the step it would buy the moment it could -- and no object is named here, so
359	     * a goal it reaches is replaced by the next one with no edit.
360	     */
361	    private function savingsGoal(PlanetService $planet, AiProfile $profile): ?SavingsGoal
362	    {
363	        // The profile's own cast is the gate: a strategy the module does not manage leaves the
364	        // balance alone, so nothing is held back and the account spends as before.
365	        if ($profile->stockpile_strategy !== AiStockpileStrategy::GoalSaver) {
366	            return null;
367	        }
368	
369	        $candidate = $this->savingCandidate($planet, $profile);
370	        if ($candidate === null) {
371	            return null;
372	        }
373	
374	        $machineName = ObjectService::getObjectById($candidate->buildingId)->machine_name;
375	
376	        return app()->makeWith(SavingsGoal::class, [
377	            'cost' => ObjectService::getObjectPrice($machineName, $planet),
378	            'objectId' => $candidate->buildingId,
379	        ]);
380	    }
381	
382	    /**
383	     * Whether the planet can pay for this candidate out of what the goal leaves spendable.
384	     *
385	     * A saving player holds the goal's price back and spends what is left over, so a cheaper upgrade
386	     * that would burn the reserved pile waits its turn. The goal's own purchase is the exception:
387	     * spending the reserve is what the reserve is for.
388	     *
389	     * The comparison is against the price alone, because the reserve already is the margin that must
390	     * survive the purchase: the goal was named precisely because the planet cannot yet pay its price
391	     * plus the same floor, so spendable = available - reserved is always below that floor and a price
392	     * plus floor again can never fit inside it. Measured that way the branch never passes and a goal
393	     * saver stops playing entirely -- frozen on every planet until the goal is reached, which is the
394	     * strategy deciding *whether* the account spends rather than how (PERS-007). Every other spend
395	     * still has to clear refusal()'s price-plus-reserve gate, so the floor is not lost, only not
396	     * charged twice against the reserve that exists to carry it.
397	     */
398	    private function canSpendFor(PlanetService $planet, ?SavingsGoal $goal, BuildCandidate $candidate): bool
399	    {
400	        if ($goal === null || $goal->covers($candidate->buildingId)) {
401	            return true;
402	        }
403	
404	        $price = ObjectService::getObjectPrice(ObjectService::getObjectById($candidate->buildingId)->machine_name, $planet);
405	        $spendable = $goal->spendable($planet->getResources());
406	
407	        return $spendable->metal->get() >= $price->metal->get()
408	            && $spendable->crystal->get() >= $price->crystal->get()
409	            && $spendable->deuterium->get() >= $price->deuterium->get();
410	    }
411	
412	    /**
413	     * The same question for a technology, asked the way the host's research page asks it.
414	     *
415	     * Research is account-wide on the host's screen while its queue and its requirements are per
416	     * planet, so the planet that answers is the planet whose laboratory carries it. Nothing here
417	     * names a technology: the price, the requirement graph and the queue are all the host's.
418	     */
419	    private function queueableResearch(PlanetService $planet, BuildCandidate $candidate): ?QueueableResearch
420	    {
421	        $machineName = ObjectService::getObjectById($candidate->buildingId)->machine_name;
422	
423	        // A technology already in research anywhere on the account is not offered again: the host
424	        // would take the row and then cancel it, so the capability is withheld instead of the
425	        // decision being spent on a refusal.
426	        if ($this->researchQueueService->activeResearchQueueItemCount($planet->getPlayer(), $candidate->buildingId) > 0) {
427	            return null;
428	        }
429	
430	        $queueable = !$this->researchQueueService->retrieveQueue($planet)->isQueueFull()
431	            && ObjectService::objectRequirementsMetWithQueue($machineName, ($planet->getPlayer()?->getResearchLevel($machineName) ?? 0) + 1, $planet)
432	            && $planet->hasResources($this->withReserve($planet, ObjectService::getObjectPrice($machineName, $planet), ReserveFloor::RESEARCH_HOURS));
433	
434	        if (!$queueable) {
435	            return null;
436	        }
437	
438	        return app()->makeWith(QueueableResearch::class, [
439	            'planetId' => $planet->getPlanetId(),
440	            'researchId' => $candidate->buildingId,
441	            'reason' => $candidate->reason,
442	        ]);
443	    }
444	
445	    /**
446	     * The price plus the floor the purchase must leave behind, so affordability stays one host call.
447	     *
448	     * A resource the price does not spend keeps no floor: the floor is what must survive spending that
449	     * resource, so a purchase that costs no deuterium is not blocked by a deuterium reserve (SP5 --
450	     * saving for a drive must not freeze surplus metal and crystal).
451	     */
452	    private function withReserve(PlanetService $planet, Resources $price, float $savingHours): Resources
453	    {
454	        $floor = $this->reserveFloor->floor($planet, $savingHours);
455	
456	        return new Resources(
457	            $price->metal->get() > 0 ? $price->metal->get() + $floor->metal->get() : 0,
458	            $price->crystal->get() > 0 ? $price->crystal->get() + $floor->crystal->get() : 0,
459	            $price->deuterium->get() > 0 ? $price->deuterium->get() + $floor->deuterium->get() : 0,
460	            $price->energy->get(),
461	        );
462	    }
463	}

