  184	    app()->makeWith(ProcessAiWork::class, ['workItemId' => $session->id])->handle();
  185	
  186	    expect(AiDecisionTrace::query()->where('work_item_id', $session->id)->firstOrFail()->selected_action)->toBe(AiCandidateActionType::DoNothing)
