  191	test('it offers a vacationing account no capability and it decides nothing', function (): void {
  192	    config(['ai.cognition.conversation.enabled' => false]);
  193	    $profile = capabilityProfile($this->currentUserId);
  194	    $this->planetAddResources(capabilityPlenty());
  195	    User::query()->whereKey($this->currentUserId)->update(['vacation_mode' => true]);
  196	
  197	    expect(capabilityOwnedState($this->currentUserId)['available_actions'])->toBe([])
  198	        ->and(capabilityOwnedState($this->currentUserId)['account_state'])->toBe(AiAccountState::Suspended->value);
  199	
  200	    $session = capabilitySession($profile, 'vacation');
  201	    app()->makeWith(ProcessAiWork::class, ['workItemId' => $session->id])->handle();
  202	
  203	    expect(AiDecisionTrace::query()->where('work_item_id', $session->id)->firstOrFail()->selected_action)->toBe(AiCandidateActionType::DoNothing)
  204	        ->and(AiWorkItem::query()->where('player_id', $profile->player_id)->where('kind', AiWorkKind::BuildFirstBuilding)->count())->toBe(0);
  205	});
  206	
  207	// Research is the capability the building chain cannot reach by building: a technology never stands on
  208	// a planet, so the same plan hands it to the research queue instead -- and until it had one, six later
  209	// capabilities were permanently unreachable.
  210	test('it publishes the research capability and queues the technology the plan approved', function (): void {
  211	    config(['ai.cognition.conversation.enabled' => false]);
