311	/**
312	 * The cheapest host ambition this planet cannot produce yet -- the same reading the chain itself
313	 * takes, restated from the host catalogue so the expectation is never the implementation.
314	 */
315	function chainCheapestUnmetAmbition(PlanetService $planet): GameObject
316	{
317	    $objects = [...ObjectService::getResearchObjects(), ...ObjectService::getUnitObjects()];
318	    $player = $planet->getPlayer();
319	    // An account with no ship that can fly goes for a hull before any technology.
320	    $flying = static fn (GameObject $object): bool => $object instanceof UnitObject
321	        && $object->properties->speed->calculate($player)->totalValue > 0;
322	    usort($objects, static fn (GameObject $left, GameObject $right): int => [! $flying($left), $left->price->resources->sum()] <=> [! $flying($right), $right->price->resources->sum()]);
323	
324	    foreach ($objects as $object) {
325	        foreach (ObjectService::getRecursiveRequirements($object->machine_name) as $machineName => $level) {
326	            $current = ObjectService::getObjectByMachineName($machineName)->type === GameObjectType::Research
327	                ? ($planet->getPlayer()?->getResearchLevel($machineName) ?? 0)
328	                : $planet->getObjectLevel($machineName);
329	
330	            if ($current < $level) {
331	                return $object;
332	            }
333	        }
334	    }
335	
336	    throw new RuntimeException('the host catalogue offers no ambition this planet cannot produce');
337	}
