375	/** Plans one step, queues it through the host queue that accepts it and lets the host finish it. */
376	function chainQueueOnce(int $playerId, int $planetId): string
377	{
378	    $plan = app(QueueableBuildingPlanner::class)->plan($playerId);
379	    expect($plan)->not->toBeNull();
380	
381	    $stepId = chainStepId($plan);
382	    $result = $plan instanceof QueueableResearch
383	        ? app(QueueAiResearch::class)->handle($playerId, $planetId, $stepId)
384	        : app(QueueAiBuilding::class)->handle($playerId, $planetId, $stepId);
385	    expect($result->successful)->toBeTrue($result->reason);
386	
387	    BuildingQueue::query()->where('planet_id', $planetId)->update(['time_end' => now()->subSecond()->getTimestamp()]);
388	    ResearchQueue::query()->where('planet_id', $planetId)->update(['time_end' => now()->subSecond()->getTimestamp()]);
389	    $player = app(PlayerGameStateService::class)->advance($playerId, $planetId);
390	    $player->updateResearchQueue();
391	    app(PlanetServiceFactory::class)->makeForPlayer($player, $planetId, false)->updateBuildingQueue();
392	
393	    return $plan->reason;
394	}
