423	/**
424	 * Every prerequisite the host's requirement graph asks for, at the easiest and the deepest level any
425	 * ambition asks for. The deepest is what satisfies the whole graph; the easiest is the unlock the plan
426	 * starts with. Buildings and technologies are both in here, because a prerequisite is a prerequisite
427	 * whichever queue ends up taking it.
428	 *
429	 * @return array<string, array{easiest: int, deepest: int}>
430	 */
431	function chainHostPrerequisites(): array
432	{
433	    $levels = [];
434	
435	    $merge = static function (string $machineName, int $level) use (&$levels): void {
436	        $current = $levels[$machineName] ?? ['easiest' => $level, 'deepest' => $level];
437	        $levels[$machineName] = [
438	            'easiest' => min($current['easiest'], $level),
439	            'deepest' => max($current['deepest'], $level),
440	        ];
441	    };
442	
443	    foreach ([...ObjectService::getResearchObjects(), ...ObjectService::getUnitObjects()] as $object) {
444	        foreach (ObjectService::getRecursiveRequirements($object->machine_name) as $machineName => $level) {
445	            $merge($machineName, $level);
446	        }
447	    }
448	
449	    // A host mission that waits on a research makes that research a chain step, so "the graph is
450	    // satisfied" also has to reach the mission's own research and that research's prerequisites.
451	    foreach (GameMissionFactory::getAllMissions() as $mission) {
452	        foreach ($mission::getRequiredResearch() as $machineName => $level) {
453	            $merge($machineName, $level);
454	            foreach (ObjectService::getRecursiveRequirements($machineName) as $prerequisite => $prerequisiteLevel) {
455	                $merge($prerequisite, $prerequisiteLevel);
456	            }
457	        }
458	    }
459	
460	    return $levels;
461	}
