104	    /**
105	     * @return list<BuildCandidate> the storage that is about to overflow, then the best-paying upgrades
106	     */
107	    public function pending(PlanetService $planet, AiProfile $profile): array
108	    {
109	        return [...$this->storage($planet, $profile), ...$this->production($planet, $profile)];
110	    }
