112	    /** @return list<BuildCandidate> the best-paying production upgrades this planet can pay to widen */
113	    public function production(PlanetService $planet, AiProfile $profile): array
114	    {
115	        $horizon = $this->paybackHorizonHours($this->averageLevel($this->productionLevels($planet)));
116	
117	        return $this->rankedProduction($planet, $profile, $horizon);
118	    }
