120	    /**
121	     * E7: a full warehouse is a spend signal — the surplus is a permanent loss, so the best mine is
122	     * offered with no payback horizon and the planner spends the surplus rather than discarding it.
123	     * Empty when no resource is at capacity, so the routine order is unchanged otherwise.
124	     *
125	     * A planet that cannot build -- its fields are full, so every mine is refused -- still has one
126	     * sink left, and the spend falls back to it: the technology that spends the largest share of its
127	     * price in the capped resource (E9). The mine candidates come first, so a planet with a free
128	     * field keeps mining and only a planet that cannot build reaches the dump.
129	     *
130	     * @return list<BuildCandidate>
131	     */
132	    public function spendSurplus(PlanetService $planet, AiProfile $profile): array
133	    {
134	        if (!$this->storageIsFull($planet)) {
135	            return [];
136	        }
137	
138	        return [
139	            ...$this->rankedProduction($planet, $profile, INF),
140	            ...$this->researchDump($planet),
141	        ];
142	    }
143	
144	    /**
145	     * E9: a full warehouse the economy cannot spend on a mine -- a field-full planet -- is dumped
146	     * into the technology that spends the largest share of its price in the capped resource, so a
147	     * metal-capped planet researches the metal-heavy technology instead of a crystal-only one. The
148	     * list is host-derived: the technologies are the host's own catalogue and the price is the host's
149	     * price for the next level.
150	     *
151	     * @return list<BuildCandidate>
152	     */
153	    public function researchDump(PlanetService $planet): array
154	    {
155	        $full = $this->fullResources($planet);
156	        if ($full === []) {
157	            return [];
158	        }
159	
160	        $entries = [];
161	
162	        foreach (ObjectService::getResearchObjects() as $object) {
163	            $price = ObjectService::getObjectPrice($object->machine_name, $planet);
164	            $total = $price->sum();
165	            $spend = 0.0;
166	
167	            foreach ($full as $resource) {
168	                $spend += match ($resource) {
169	                    'metal' => $price->metal->get(),
170	                    'crystal' => $price->crystal->get(),
171	                    'deuterium' => $price->deuterium->get(),
172	                    default => 0.0,
173	                };
174	            }
175	
176	            if ($spend <= 0.0 || $total <= 0.0) {
177	                continue;
178	            }
179	
180	            // The share of the price paid in capped resources, not the absolute amount: a pure-metal
181	            // armour is a better metal dump than a drive whose crystal half is not overflowing. The
182	            // cheapest spender wins a tie, so the dump stays small and frequent rather than one huge
183	            // research.
184	            $entries[] = [
185	                'share' => $spend / $total,
186	                'total' => $total,
187	                'candidate' => app()->makeWith(BuildCandidate::class, [
188	                    'buildingId' => $object->id,
189	                    'reason' => 'economy:dump:' . $object->machine_name,
190	                ]),
191	            ];
192	        }
193	
194	        usort($entries, static function (array $left, array $right): int {
195	            return $right['share'] <=> $left['share'] ?: $left['total'] <=> $right['total'];
196	        });
197	
198	        return array_map(static fn (array $entry): BuildCandidate => $entry['candidate'], $entries);
199	    }
200	
201	    /**
202	     * The facilities and technologies a planet that is sitting on a pile builds for their own sake:
203	     * the nano factory, terraformer, depot, dock, gate and the far end of the research tree are not
204	     * production upgrades, so the payback ranking never picks them and no account ever owned one
205	     * (COVER-*). A player with six times the price in the vault and nothing urgent buys the next
206	     * thing the catalogue offers, cheapest first, a few levels each. Nothing is named: the objects are
207	     * the host's own stations and technologies, the gate is the host's requirement check, and the
208	     * queue's own refusals (planet type, free fields, price plus reserve) still apply downstream.
209	     *
210	     * @return list<BuildCandidate>
211	     */
212	    public function ambitions(PlanetService $planet): array
213	    {
214	        // A planet that produces no energy of its own is not sitting on a pile: the host throttles
215	        // everything it mines until a plant covers it, so the step that pays for itself first is that
216	        // capacity, and the facilities and technologies a pile invites wait for it. Without this the
217	        // cheapest station the pile affords came first on every unbuilt planet, and the plant every
218	        // guide opens with was never the plan's first step -- the planet then mines throttled.
219	        if ($planet->energy()->get() <= 0.0) {
220	            return [];
221	        }
222	
223	        $entries = [];
224	        $production = array_map(static fn ($object): string => $object->machine_name, ObjectService::getGameObjectsWithProduction());
225	
226	        foreach ([...ObjectService::getStationObjects(), ...ObjectService::getResearchObjects()] as $object) {
227	            if (in_array($object->machine_name, $production, true)) {
228	                continue;
229	            }
230	            if ($planet->getObjectLevel($object->machine_name) >= self::AMBITION_LEVELS) {
231	                continue;
232	            }
233	            if (!ObjectService::objectValidPlanetType($object->machine_name, $planet) || !ObjectService::objectRequirementsMet($object->machine_name, $planet)) {
234	                continue;
235	            }
236	
237	            $price = ObjectService::getObjectPrice($object->machine_name, $planet);
238	            $vault = new Resources(
239	                $price->metal->get() * self::AMBITION_VAULT,
240	                $price->crystal->get() * self::AMBITION_VAULT,
241	                $price->deuterium->get() * self::AMBITION_VAULT,
242	            );
243	            if ($price->sum() <= 0.0 || !$planet->hasResources($vault)) {
244	                continue;
245	            }
246	
247	            $entries[] = [
248	                'total' => $price->sum(),
249	                'candidate' => app()->makeWith(BuildCandidate::class, [
250	                    'buildingId' => $object->id,
251	                    'reason' => 'economy:ambition:' . $object->machine_name,
252	                ]),
253	            ];
254	        }
255	
256	        usort($entries, static fn (array $left, array $right): int => $left['total'] <=> $right['total']);
257	
258	        return array_map(static fn (array $entry): BuildCandidate => $entry['candidate'], $entries);
259	    }
