261	    /** @return list<BuildCandidate> the production upgrades whose payback lies inside the horizon */
262	    private function rankedProduction(PlanetService $planet, AiProfile $profile, float $horizon): array
263	    {
264	        $entries = [];
265	        $gains = [];
266	
267	        foreach (ObjectService::getGameObjectsWithProduction() as $object) {
268	            if (!BuildingQueueObject::accepts($object->machine_name)) {
269	                continue;
270	            }
271	
272	            $gain = $this->productionGainOfNextLevel($planet, $object->machine_name);
273	            if ($gain > 0.0) {
274	                $gains[] = [$object, $gain];
275	            }
276	        }
277	
278	        // Every object below asks the experience engine about its own history; one request for all of
279	        // them replaces a round trip per object.
280	        $this->prefetchExperience($profile, array_map(static fn (array $pair): int => (int) $pair[0]->id, $gains));
281	
282	        foreach ($gains as [$object, $gain]) {
283	            $entries[] = [
284	                'hours' => $this->paybackHours($profile, (int) $object->id, ObjectService::getObjectPrice($object->machine_name, $planet), $gain),
285	                'buildTime' => $planet->getBuildingConstructionTime($object->machine_name),
286	                'candidate' => app()->makeWith(BuildCandidate::class, [
287	                    'buildingId' => $object->id,
288	                    'reason' => 'economy:' . $object->machine_name,
289	                ]),
290	            ];
291	        }
292	
293	        $affordable = array_values(array_filter(
294	            $entries,
295	            static fn (array $entry): bool => $entry['hours'] <= $horizon,
296	        ));
297	
298	        // Shorter first on a tie: a build occupies the planet's only queue slot, so when two levels
299	        // repay equally the one that gives the slot back sooner is the better use of it.
300	        usort($affordable, static function (array $left, array $right): int {
301	            return [$left['hours'], $left['buildTime']] <=> [$right['hours'], $right['buildTime']];
302	        });
303	
304	        return array_map(static fn (array $entry): BuildCandidate => $entry['candidate'], $affordable);
305	    }
