307	    /** @return list<int> the current level of every production object, for the payback horizon */
308	    private function productionLevels(PlanetService $planet): array
309	    {
310	        $levels = [];
311	
312	        foreach (ObjectService::getGameObjectsWithProduction() as $object) {
313	            if (!BuildingQueueObject::accepts($object->machine_name)) {
314	                continue;
315	            }
316	
317	            $levels[] = $planet->getObjectLevel($object->machine_name);
318	        }
319	
320	        return $levels;
321	    }
