323	    /**
324	     * @return list<BuildCandidate> storages whose remaining capacity would fill inside an absence
325	     *
326	     * A warehouse is grown only while its fill lies in the future -- it would overflow inside this
327	     * account's own absence, so a bigger store buys the time away. A warehouse that is already full
328	     * (time to fill zero) is a spend signal, not a warehouse signal: the surplus above capacity is
329	     * fully lootable, so it is answered by the mine that spends it, never by a bigger warehouse.
330	     */
331	    public function storage(PlanetService $planet, AiProfile $profile): array
332	    {
333	        $absence = $this->absenceHours($profile);
334	        $entries = [];
335	
336	        foreach (ObjectService::getBuildingObjectsWithStorage() as $object) {
337	            $hours = $this->timeToFill($planet, $object->machine_name);
338	
339	            if ($hours === null || $hours <= 0.0 || $hours >= $absence) {
340	                continue;
341	            }
342	
343	            // One level of a warehouse at a time. The fill time above is measured on the built
344	            // level, so a level already in the queue reads as still-needed on every session and the
345	            // account chains levels until the whole queue holds multi-hour builds and nothing else
346	            // can be queued at all (measured on the canary, 29 Sep 2026). The queue is the host's,
347	            // so a storage object a mod adds is covered by the same check.
348	            if ($this->buildingQueue->activeBuildingQueueItemCount($planet, $object->id) > 0) {
349	                continue;
350	            }
351	
352	            // A warehouse that takes longer to build than the absence it is meant to cover cannot
353	            // be ready before the account returns, so it is not worth the one queue slot: storage
354	            // cost doubles each level while its build-time factor collapses, so a high-level
355	            // warehouse takes days and would park the whole build queue. The surplus is then the
356	            // spend signal's to handle.
357	            $buildHours = $planet->getBuildingConstructionTime($object->machine_name) / 3600.0;
358	            if ($buildHours >= $absence) {
359	                continue;
360	            }
361	
362	            $entries[] = ['hours' => $hours, 'candidate' => app()->makeWith(BuildCandidate::class, [
363	                'buildingId' => $object->id,
364	                'reason' => 'storage:' . $object->machine_name,
365	            ])];
366	        }
367	
368	        usort($entries, static fn (array $left, array $right): int => $left['hours'] <=> $right['hours']);
369	
370	        return array_map(static fn (array $entry): BuildCandidate => $entry['candidate'], $entries);
371	    }
