373	    /**
374	     * The storage upgrade a build needs before its price can even fit (E8).
375	     *
376	     * A young planet's next mine can cost more than its warehouse holds, so the
377	     * build can never be afforded however long the mines run; the host rejects
378	     * it and the account would stall. A player grows the store that raises the
379	     * blocking resource first. Returns that store, cheapest first, or empty when
380	     * the next build fits or no production candidate is worth building.
381	     *
382	     * @return list<BuildCandidate>
383	     */
384	    public function storageForPrice(PlanetService $planet, AiProfile $profile): array
385	    {
386	        $next = $this->production($planet, $profile)[0] ?? null;
387	        if ($next === null) {
388	            return [];
389	        }
390	
391	        $price = ObjectService::getObjectPrice(
392	            ObjectService::getObjectById($next->buildingId)->machine_name,
393	            $planet,
394	        );
395	        $blocking = $this->blockingResources($planet, $price);
396	        if ($blocking === []) {
397	            return [];
398	        }
399	
400	        $entries = [];
401	        foreach (ObjectService::getBuildingObjectsWithStorage() as $object) {
402	            if (!$this->raisesAny($planet, $object->machine_name, $blocking)) {
403	                continue;
404	            }
405	
406	            $entries[] = [
407	                'price' => $this->metalEquivalent(ObjectService::getObjectPrice($object->machine_name, $planet)),
408	                'candidate' => app()->makeWith(BuildCandidate::class, [
409	                    'buildingId' => $object->id,
410	                    'reason' => 'storage:' . $object->machine_name,
411	                ]),
412	            ];
413	        }
414	
415	        usort($entries, static fn (array $left, array $right): int => $left['price'] <=> $right['price']);
416	
417	        return array_map(static fn (array $entry): BuildCandidate => $entry['candidate'], $entries);
418	    }
