420	    /** @return list<string> the resources whose next-build price exceeds this planet's storage */
421	    private function blockingResources(PlanetService $planet, Resources $price): array
422	    {
423	        $blocking = [];
424	        if ($price->metal->get() > $planet->metalStorage()->get()) {
425	            $blocking[] = 'metal';
426	        }
427	        if ($price->crystal->get() > $planet->crystalStorage()->get()) {
428	            $blocking[] = 'crystal';
429	        }
430	        if ($price->deuterium->get() > $planet->deuteriumStorage()->get()) {
431	            $blocking[] = 'deuterium';
432	        }
433	
434	        return $blocking;
435	    }
