437	    /**
438	     * Whether a storage object raises the capacity of at least one resource the
439	     * next build is blocked on, by the host's own storage formula asked twice.
440	     *
441	     * @param list<string> $blocking
442	     */
443	    private function raisesAny(PlanetService $planet, string $machineName, array $blocking): bool
444	    {
445	        $level = $planet->getObjectLevel($machineName);
446	        $added = $planet->getBuildingMaxStorage($machineName, $level + 1);
447	        $current = $planet->getBuildingMaxStorage($machineName);
448	
449	        return (in_array('metal', $blocking, true) && $added->metal->get() > $current->metal->get())
450	            || (in_array('crystal', $blocking, true) && $added->crystal->get() > $current->crystal->get())
451	            || (in_array('deuterium', $blocking, true) && $added->deuterium->get() > $current->deuterium->get());
452	    }
