454	    /**
455	     * Whether any resource is at or above this planet's storage capacity — the full-warehouse
456	     * state that makes production overflow a permanent loss (E7).
457	     */
458	    private function storageIsFull(PlanetService $planet): bool
459	    {
460	        return $this->fullResources($planet) !== [];
461	    }
