463	    /**
464	     * @return list<string> the resources this planet currently holds at or above capacity
465	     */
466	    private function fullResources(PlanetService $planet): array
467	    {
468	        $stored = $planet->getResources();
469	
470	        return array_keys(array_filter([
471	            'metal' => $planet->metalStorage()->get() <= $stored->metal->get(),
472	            'crystal' => $planet->crystalStorage()->get() <= $stored->crystal->get(),
473	            'deuterium' => $planet->deuteriumStorage()->get() <= $stored->deuterium->get(),
474	        ]));
475	    }
