477	    /**
478	     * Hours until the storage that raises a resource is full, or null when this object cannot help.
479	     *
480	     * The capacity a level adds is the host's own storage formula asked twice, so the module never
481	     * names a storage object, and a resource with no production on this planet can never fill --
482	     * which is why a metal depot is not built on a planet with no mine.
483	     */
484	    private function timeToFill(PlanetService $planet, string $machineName): ?float
485	    {
486	        $level = $planet->getObjectLevel($machineName);
487	        $added = $planet->getBuildingMaxStorage($machineName, $level + 1);
488	
489	        $current = $planet->getBuildingMaxStorage($machineName);
490	        $stored = $planet->getResources();
491	
492	        $hours = array_filter([
493	            $this->fillHours($planet->metalStorage(), $stored->metal, $planet->getMetalProductionPerHour(), $added->metal->get() - $current->metal->get()),
494	            $this->fillHours($planet->crystalStorage(), $stored->crystal, $planet->getCrystalProductionPerHour(), $added->crystal->get() - $current->crystal->get()),
495	            $this->fillHours($planet->deuteriumStorage(), $stored->deuterium, $planet->getDeuteriumProductionPerHour(), $added->deuterium->get() - $current->deuterium->get()),
496	        ], static fn (?float $value): bool => $value !== null);
497	
498	        return $hours === [] ? null : min($hours);
499	    }
500	
501	    /**
502	     * How long this account is typically away between two visits, from its own routine.
503	     *
504	     * The persona already states how often it looks at the account, so the gap is that figure's
505	     * reciprocal and no new setting is introduced. It is floored at one session a day so a profile
506	     * with an unset or implausible routine still has a horizon rather than an infinite one.
507	     */
508	    private function absenceHours(AiProfile $profile): float
509	    {
510	        return self::HOURS_PER_DAY / max(1, RoutineProfile::fromAiProfile($profile)->sessionsPerDay);
511	    }
512	
513	    private function fillHours(Resource $capacity, Resource $stored, float $productionPerHour, float $addedCapacity): ?float
514	    {
515	        // A storage that does not raise this resource, or a planet that does not produce it, has
516	        // nothing that can fill, so it is not a storage decision.
517	        if ($addedCapacity <= 0.0 || $productionPerHour <= 0.0) {
518	            return null;
519	        }
520	
521	        return max(0.0, $capacity->get() - $stored->get()) / $productionPerHour;
522	    }
523	
524	    private function paybackHours(AiProfile $profile, int $objectId, Resources $price, float $gain): float
525	    {
526	        return ($this->metalEquivalent($price) / $gain)
527	            * (1 + $this->personaVariation($profile, $objectId))
528	            * (1 - $this->rememberedBias($profile, $objectId));
529	    }
530	
531	    /** What the host's own production calculation says the next level adds, in one currency. */
532	    private function productionGainOfNextLevel(PlanetService $planet, string $machineName): float
533	    {
534	        $level = $planet->getObjectLevel($machineName);
535	
536	        // The host scales a building's reported output by the planet's current energy factor, so a
537	        // planet running a deficit reports nothing for the mine it would fix. Asking both levels at
538	        // 100% is what makes the comparison a property of the building rather than of today's energy.
539	        return $this->metalEquivalent($planet->getObjectProduction($machineName, $level + 1, true))
540	            - $this->metalEquivalent($planet->getObjectProduction($machineName, $level, true));
541	    }
542	
543	    private function metalEquivalent(Resources $resources): float
544	    {
545	        return $resources->metal->get()
546	            + self::CRYSTAL_WEIGHT * $resources->crystal->get()
547	            + self::DEUTERIUM_WEIGHT * $resources->deuterium->get();
548	    }
549	
550	    /** @param list<int> $levels */
551	    private function averageLevel(array $levels): float
552	    {
553	        return $levels === [] ? 0.0 : array_sum($levels) / count($levels);
554	    }
555	
556	    private function paybackHorizonHours(float $averageLevel): float
557	    {
558	        return min(
559	            self::PAYBACK_CAP_HOURS,
560	            self::PAYBACK_BASE_HOURS * (1 + $averageLevel / self::LEVELS_PER_SLACK),
561	        );
562	    }
563	
564	    /**
565	     * The persona's taste, up to a few per cent either way.
566	     *
567	     * A veteran's order is the arithmetic's order; a novice's is noisier. The value is derived from
568	     * the account's own seed, so one account has one order it can reproduce, and two accounts with
569	     * the same numbers still differ from each other.
570	     */
571	    private function personaVariation(AiProfile $profile, int $objectId): float
572	    {
573	        $unit = (crc32($profile->random_seed . ':economy:' . $objectId) % 1000) / 1000;
574	
575	        return ($unit - 0.5) * $profile->skill_band->variationWeight() / 100;
576	    }
577	
578	    /**
579	     * A bounded nudge from this account's own finalized outcomes.
580	     *
581	     * Only the built object is known before the account has built anything, so every other feature
582	     * stays unknown and similarity is decided by the object alone. Only a case that matches on every
583	     * feature the module knows about is evidence about this choice, because the engine's similarity
584	     * is a mean over shared features -- a partial score describes a different situation rather than
585	     * a weaker precedent, and object identifiers compare numerically, which would otherwise make an
586	     * outcome for one building look like faint evidence for its neighbour. An uncertain outcome is
587	     * worth correspondingly less than a settled one, and the whole term is capped so a remembered
588	     * outcome can never outvote the arithmetic.
589	     */
590	    /** @param list<int> $objectIds */
591	    private function prefetchExperience(AiProfile $profile, array $objectIds): void
592	    {
593	        if ($objectIds === [] || !$this->experience instanceof PrefetchesExperience || app(AiRuntimeSettings::class)->experienceDecisionWeight() === 0) {
594	            return;
595	        }
596	
597	        $this->experience->prefetch(array_map(fn (int $objectId): ExperienceQuery => $this->experienceQuery($profile, $objectId), $objectIds));
598	    }
599	
600	    private function experienceQuery(AiProfile $profile, int $objectId): ExperienceQuery
601	    {
602	        return app()->makeWith(ExperienceQuery::class, [
603	            'playerId' => $profile->player_id,
604	            'family' => AiExperienceCaseFamily::BuildingUpgrade,
605	            'featureVersion' => AiExperienceFeatureVersion::BuildingUpgradeV1->value,
606	            'rulesetVersion' => AiExperienceRulesetVersion::HostBuildingCompletionV1->value,
607	            'features' => [AiBuildingExperienceFeature::ObjectId->value => $objectId],
608	            'limit' => self::MAXIMUM_CASES,
609	        ]);
610	    }
611	
612	    private function rememberedBias(AiProfile $profile, int $objectId): float
613	    {
614	        $weight = app(AiRuntimeSettings::class)->experienceDecisionWeight();
615	
616	        if ($weight === 0) {
617	            return 0.0;
618	        }
619	
620	        $ranked = $this->experience->rankSimilarExperiences($this->experienceQuery($profile, $objectId));
621	
622	        $evidence = array_filter(array_map(
623	            static fn (RankedExperience $case): float => $case->similarity >= 1.0
624	                ? $case->utility * (1 - $case->uncertainty)
625	                : 0.0,
626	            $ranked,
627	        ), static fn (float $value): bool => $value !== 0.0);
628	
629	        if ($evidence === []) {
630	            return 0.0;
631	        }
632	
633	        $bias = $weight / 100 * array_sum($evidence) / count($evidence);
634	
635	        return max(-self::EXPERIENCE_MAXIMUM_SHARE, min(self::EXPERIENCE_MAXIMUM_SHARE, $bias));
636	    }
637	}

