 16	/**
 17	 * An archetype's written doctrine (`resources/doctrine/<archetype>.yaml`): the opening build order, the
 18	 * research path, and the fleet and defence templates (architecture step 4).
 19	 *
 20	 * The files name objects, as data (Gate 1 as amended 3 Oct 2026). This class names none: an entry the host
 21	 * does not have is skipped, and when a list is done or a template holds nothing the host can build, the
 22	 * caller's generic rule decides, so a modded object stays reachable.
 23	 *
 24	 * Which list the account follows is its phase (`phases: <phase>: <key>`, architecture step 4), and the
 25	 * flat list is the fallback every other phase reads: a file without a phase block behaves exactly as
 26	 * before, and a guide can send an opening account down a different path from a settled one.
 27	 */
 28	class ArchetypeDoctrine
 29	{
 30	    private const DIRECTORY = '/resources/doctrine/';
 31	
 32	    /** @var array<string, array<string, mixed>> */
 33	    private static array $files = [];
 34	
 35	    /**
 36	     * The next opening step this planet has not reached, as a building candidate: the build list runs in
 37	     * order, a step already done is skipped, and research steps are left to the research path.
 38	     *
 39	     * @return list<BuildCandidate>
 40	     */
 41	    public function openingStep(AiArchetype $archetype, PlanetService $planet): array
 42	    {
 43	        foreach ($this->steps($archetype, 'opening', $this->phase($planet->getPlayer())) as [$machineName, $level]) {
 44	            $object = $this->object($machineName);
 45	            if ($object === null || $object->type === GameObjectType::Research) {
 46	                continue;
 47	            }
 48	            if (!ObjectService::objectValidPlanetType($machineName, $planet)) {
 49	                continue;
 50	            }
 51	            if ($planet->getObjectLevel($machineName) >= $level) {
 52	                continue;
 53	            }
 54	
 55	            return [new BuildCandidate($object->id, 'doctrine:opening:' . $machineName . ':' . $level)];
 56	        }
 57	
 58	        return [];
 59	    }
 60	
 61	    /**
 62	     * The next technology on the archetype's path the account has not reached (the opening's research rows
 63	     * first, then the path), as a candidate for the lab.
 64	     *
 65	     * @return list<BuildCandidate>
 66	     */
 67	    public function researchStep(AiArchetype $archetype, PlayerService $player): array
 68	    {
 69	        $phase = $this->phase($player);
 70	        $rows = [...$this->steps($archetype, 'opening', $phase), ...$this->steps($archetype, 'research_path', $phase)];
 71	
 72	        foreach ($rows as [$machineName, $level]) {
 73	            $object = $this->object($machineName);
 74	            if ($object === null || $object->type !== GameObjectType::Research) {
 75	                continue;
 76	            }
 77	            if ($player->getResearchLevel($machineName) >= $level) {
 78	                continue;
 79	            }
 80	
 81	            return [new BuildCandidate($object->id, 'doctrine:research:' . $machineName . ':' . $level)];
 82	        }
 83	
 84	        return [];
 85	    }
 86	
 87	    /**
 88	     * The template's hull furthest below its share of what the account owns, among the hulls `$buildable`
 89	     * accepts; null when the archetype has no template or nothing in it can be built.
 90	     *
 91	     * @param array<string, int> $owned machine name => units the account owns
 92	     * @param callable(string): bool $buildable
 93	     */
 94	    public function nextTemplateUnit(AiArchetype $archetype, string $template, array $owned, callable $buildable): ?string
 95	    {
 96	        $shares = $this->file($archetype)[$template] ?? [];
 97	        if (!is_array($shares) || $shares === []) {
 98	            return null;
 99	        }
100	
101	        $total = max(1, array_sum(array_map(static fn (string $name): int => $owned[$name] ?? 0, array_keys($shares))));
102	        $weight = max(1, array_sum($shares));
103	        $best = null;
104	        $bestGap = -INF;
105	
106	        foreach ($shares as $machineName => $share) {
107	            if ($this->object((string) $machineName) === null || !$buildable((string) $machineName)) {
108	                continue;
109	            }
110	
111	            $gap = ((float) $share / $weight) - (($owned[$machineName] ?? 0) / $total);
112	            if ($gap > $bestGap) {
113	                $best = (string) $machineName;
114	                $bestGap = $gap;
115	            }
116	        }
117	
118	        return $best;
119	    }
120	
121	    /**
122	     * The account's game phase, which decides which list a guide's file gives it (architecture step 4).
123	     * No player (a detached planet read) leaves the phase unknown, and an unknown phase follows the flat
124	     * list, so nothing that reads the doctrine can be broken by a missing owner.
125	     */
126	    private function phase(?PlayerService $player): ?GamePhase
127	    {
128	        return $player === null ? null : app(GamePhaseMachine::class)->of($player);
129	    }
130	
131	    /**
132	     * The ordered rows of one list, as data: the phase's own list when the file writes one, else the flat
133	     * list every phase shares.
134	     *
135	     * @return list<array{0: string, 1: int}>
136	     */
137	    private function steps(AiArchetype $archetype, string $key, ?GamePhase $phase = null): array
138	    {
139	        $file = $this->file($archetype);
140	        $rows = $file[$key] ?? [];
141	
142	        if ($phase !== null) {
143	            $phases = $file['phases'] ?? null;
144	            $phaseRow = is_array($phases) ? ($phases[$phase->value] ?? null) : null;
145	            $phaseRows = is_array($phaseRow) ? ($phaseRow[$key] ?? null) : null;
146	            $rows = is_array($phaseRows) ? $phaseRows : $rows;
147	        }
148	
149	        $steps = [];
150	
151	        foreach (is_array($rows) ? $rows : [] as $row) {
152	            if (is_array($row) && isset($row[0], $row[1])) {
153	                $steps[] = [(string) $row[0], (int) $row[1]];
154	            }
155	        }
156	
157	        return $steps;
158	    }
159	
160	    private function object(string $machineName): ?object
161	    {
162	        try {
163	            return ObjectService::getObjectByMachineName($machineName);
164	        } catch (Throwable) {
165	            return null;
166	        }
167	    }
168	
169	    /** @return array<string, mixed> */
170	    private function file(AiArchetype $archetype): array
171	    {
172	        $name = match ($archetype) {
173	            AiArchetype::Trader => 'miner',
174	            AiArchetype::Casual => 'hybrid',
175	            default => strtolower($archetype->name),
176	        };
177	
178	        if (!array_key_exists($name, self::$files)) {
179	            $path = dirname(__DIR__, 3) . self::DIRECTORY . $name . '.yaml';
180	            $parsed = is_file($path) ? Yaml::parseFile($path) : [];
181	            self::$files[$name] = is_array($parsed) ? $parsed : [];
182	        }
183	
184	        return self::$files[$name];
185	    }
186	}

