  8	/**
  9	 * The capacity a planet wants before its next production upgrade outdraws it.
 10	 *
 11	 * A player builds the plant before the mine that would run the planet short, not after the mines have
 12	 * already stalled: the host multiplies a planet's whole production by the ratio of the energy it can
 13	 * cover, so a planet in deficit mines at a fraction of what its mines say and everything it builds
 14	 * afterwards is worth less. That is why the canonical opening in every guide starts with the solar
 15	 * plant rather than with a mine, and why this asks about the *next* level instead of about the balance
 16	 * as it stands.
 17	 *
 18	 * Which buildings can answer it is the host's decision, not a list of names: the candidates are the
 19	 * objects the host itself reports as producing, filtered to those the building queue accepts whose next
 20	 * level puts energy out. Whatever an extension adds to that set is offered here the moment the host
 21	 * knows about it. The cheapest capacity is tried first, which is why a player builds a solar plant long
 22	 * before a fusion reactor.
 23	 *
 24	 * Only capacity is produced here. When the account cannot pay for it yet the plan falls through to
 25	 * whatever else the host accepts, and the account keeps playing -- which is what a player does while
 26	 * saving.
 27	 */
 28	class EnergyCapacity
 29	{
 30	    /** @return list<BuildCandidate> the cheapest capacity, or nothing when the planet is not short */
 31	    public function pending(PlanetService $planet): array
 32	    {
 33	        if ($this->shortfall($planet) <= 0.0) {
 34	            return [];
 35	        }
 36	
 37	        $candidates = [];
 38	
 39	        foreach (ObjectService::getGameObjectsWithProduction() as $object) {
 40	            if (!BuildingQueueObject::accepts($object->machine_name)) {
 41	                continue;
 42	            }
 43	
 44	            if ($this->energyGainOfNextLevel($planet, $object->machine_name) <= 0) {
 45	                continue;
 46	            }
 47	
 48	            $candidates[] = [
 49	                'price' => ObjectService::getObjectPrice($object->machine_name, $planet)->sum(),
 50	                'candidate' => app()->makeWith(BuildCandidate::class, [
 51	                    'buildingId' => $object->id,
 52	                    'reason' => 'energy:' . $object->machine_name,
 53	                ]),
 54	            ];
 55	        }
 56	
 57	        usort($candidates, static fn (array $left, array $right): int => $left['price'] <=> $right['price']);
 58	
 59	        return array_map(static fn (array $entry): BuildCandidate => $entry['candidate'], $candidates);
 60	    }
 61	
 62	    /**
 63	     * How much power the planet wants: the deficit it is already in, or the one its next production
 64	     * upgrade would create, whichever is larger. Zero when the balance covers the next step.
 65	     *
 66	     * The magnitude is public because a planet that cannot buy the capacity has one other route --
 67	     * the yard -- and how many power units that route needs is this question's answer, not a second
 68	     * calculation over the same host numbers.
 69	     */
 70	    public function shortfall(PlanetService $planet): float
 71	    {
 72	        $energy = (float) $planet->energy()->get();
 73	        $deficit = -$energy;
 74	
 75	        // A consumer is any production object whose next level draws more than it makes, so the
 76	        // planet is short when one of those upgrades would land it below zero.
 77	        foreach (ObjectService::getGameObjectsWithProduction() as $object) {
 78	            $gain = $this->energyGainOfNextLevel($planet, $object->machine_name);
 79	
 80	            if ($gain < 0.0) {
 81	                $deficit = max($deficit, -($energy + $gain));
 82	            }
 83	        }
 84	
 85	        return max(0.0, $deficit);
 86	    }
 87	
 88	    /**
 89	     * What the host's own production calculation says the next level adds to the energy balance.
 90	     *
 91	     * The host scales a building's reported output by the planet's current energy factor, so a planet
 92	     * already in deficit reports nothing at all for the very plant that would fix it. Comparing raw
 93	     * output is what makes the question answerable, so both levels are asked for at 100%.
 94	     */
 95	    private function energyGainOfNextLevel(PlanetService $planet, string $machineName): float
 96	    {
 97	        $level = $planet->getObjectLevel($machineName);
 98	
 99	        return (float) $planet->getObjectProduction($machineName, $level + 1, true)->energy->get()
100	            - (float) $planet->getObjectProduction($machineName, $level, true)->energy->get();
101	    }
102	}

  185	// naked while every counter above read healthy (found 29 Sep 2026). These are the three shapes the
  186	// damage took, stated as thresholds so a human reading the log sees the defect named. They are
  187	// measurement thresholds for this log, not module policy: nothing in the module reads them.
  188	//
  189	//   NAKED_BESIDE_WALLED  an account with a planet at zero defence while a sibling holds a real wall
  190	//   WALL_CEILING         one planet holding more defence units than any single planet needs
  191	//   ALLIANCE_SHARE       one alliance holding more than this share of the AI accounts
  192	//   IDLE_QUEUES          an account that played in the last hour with most buildable planets' queues empty
  193	//   UNIVERSE_SPEED       the economy or a fleet speed above the 1000x grand-test protocol
  194	$nakedBesideWalled = [];
  195	$overCeiling = [];
  196	$WALL_CEILING = 20_000;
  197	$ALLIANCE_SHARE = 0.6;
