  207	// walls it once the yard exists, so a planet is only counted bare after that lead time.
  208	$planetQuery->where('created_at', '<=', now()->subHour());
  209	if (Schema::hasColumn('planets', 'planet_type')) {
  210	    $planetQuery->where('planet_type', '!=', 3);
  211	}
  212	
  213	$byAccount = [];
  214	foreach ($planetQuery->selectRaw("user_id, id, ($defenceSum) as defence")->get() as $row) {
  215	    $byAccount[(int) $row->user_id][] = ['id' => (int) $row->id, 'defence' => (int) $row->defence];
  216	}
