 21	/**
 22	 * Base class for tests that require an authenticated account, isolated per test.
 23	 *
 24	 * Wraps each test in a database transaction (DatabaseTransactions) so no rows leak between
 25	 * tests and tests no longer depend on execution order. Creates the user via the standard
 26	 * Eloquent factories (User::factory()) + actingAs() instead of a real HTTP /register +
 27	 * /login round-trip, and starts the session up-front so csrf_token() returns a real token
 28	 * (CSRF stays fully enforced).
 29	 *
 30	 * Shared test helpers are grouped into focused traits in Tests\Traits (planet state,
 31	 * page assertions, build requests, messages and foreign fixtures).
 32	 */
 33	abstract class IsolatedAccountTestCase extends TestCase
 34	{
 35	    use DatabaseTransactions;
 36	    use ManagesPlanetState;
 37	    use AssertsPageState;
 38	    use SubmitsBuildRequests;
 39	    use AssertsMessages;
 40	    use CreatesForeignFixtures;
 41	
 42	    protected int $currentUserId = 0;
 43	    protected string $currentUsername = '';
 44	    protected int $userPlanetAmount = 2;
 45	
 46	    protected int $currentPlanetId = 0;
 47	
 48	    /**
 49	     * Default computer technology level for newly created users.
 50	     * Tests that require a different level can override this property.
 51	     */
 52	    protected int $defaultComputerTechnologyLevel = 5;
 53	
 54	    /**
 55	     * Test user main planet.
 56	     */
 57	    protected PlanetService $planetService;
 58	
 59	    /**
 60	     * Test user second planet.
 61	     */
 62	    protected ?PlanetService $secondPlanetService = null;
 63	
 64	    /**
 65	     * The default test time that is used to start tests with.
 66	     */
 67	    protected Carbon $defaultTestTime;
 68	
 69	    /**
 70	     * Set up common test components.
 71	     */
 72	    protected function setUp(): void
 73	    {
 74	        parent::setUp();
 75	
 76	        // Set default test time to 2024-01-01 00:00:00 to ensure all tests have the same starting point.
 77	        $this->travelTo(Date::create(2024, 1, 1, 0, 0, 0));
 78	
 79	        // Set default server settings for all tests.
 80	        $settingsService = resolve(SettingsService::class);
 81	        $settingsService->set('economy_speed', 8);
 82	        // Establish a full speed baseline so settings mutated by earlier tests can't leak
 83	        // into this one. Without this, e.g. ResearchQueueTest sets research_speed=2 which
 84	        // then changes timing in unrelated tests like VacationModeTest (see #1021).
 85	        $settingsService->set('research_speed', 1);
 86	
 87	        // Set amount of planets to be created for the user because planet switching
 88	        // is a part of the test suite.
 89	        $settingsService->set('registration_planet_amount', $this->userPlanetAmount);
 90	
 91	        // Reset planet assignment to start within valid galaxy bounds.
 92	        // This ensures tests don't fail when the database has planets in galaxies
 93	        // beyond the configured max (e.g., from previous test runs with different settings).
 94	        $maxGalaxies = $settingsService->numberOfGalaxies();
 95	        $lastAssignedGalaxy = (int)$settingsService->get('last_assigned_galaxy', 1);
 96	        if ($lastAssignedGalaxy > $maxGalaxies) {
 97	            $settingsService->set('last_assigned_galaxy', 1);
 98	            $settingsService->set('last_assigned_system', 1);
 99	        }
100	
101	        // Create a new user and login so we can access ingame features.
102	        $this->createAndLoginUser();
103	
104	        // Start the session up-front so csrf_token() returns a real token.
105	        $this->app['session']->driver()->start();
106	    }
107	
108	    /**
109	     * Refreshing the application creates a connection outside this test's transaction,
110	     * making its fixtures unavailable. Remove the underlying cache dependency before
111	     * converting a test that needs this behavior.
112	     */
113	    final public function reloadApplication(): void
114	    {
115	        throw new LogicException('reloadApplication() is incompatible with IsolatedAccountTestCase.');
116	    }
117	
118	    /**
119	     * Create a user and authenticate without HTTP round-trips.
120	     */
121	    protected function createAndLoginUser(): void
122	    {
123	        // Seed the planet allocator so the homeworld lands at a fixed, collision-safe
124	        // system far from both the seeded Legor admin account (1:1:2) and any planets
125	        // leaked by non-transactional tests (Admin/Ban/Buddy populate systems 1..N).
126	        // Without this, position-based colonisation tests collide with Legor's 1:1:2, and
127	        // the distance between the two home planets drifts (raising deuterium fuel past
128	        // the budget in FleetDispatchLargeResourcesTest).
129	        resolve(SettingsService::class)->set('last_assigned_system', 400);
130	
131	        $user = $this->createUser();
132	
133	        $this->actingAs($user);
134	
135	        $this->currentUserId = $user->id;
136	        $this->currentUsername = $user->username;
137	
138	        // Wire up planet services from the real factory.
139	        $playerServiceFactory = resolve(PlayerServiceFactory::class);
140	        $playerService = $playerServiceFactory->make($user->id, true);
141	
142	        $this->planetService = $playerService->planets->current();
143	        $this->currentPlanetId = $this->planetService->getPlanetId();
144	
145	        // Reproduce the page-load side effects real registration triggers.
146	        $playerService->update();
147	        $this->planetService->update();
148	
149	        $allPlanets = $playerService->planets->allPlanets();
150	        if (isset($allPlanets[1])) {
151	            $this->secondPlanetService = $allPlanets[1];
152	        }
153	
154	        // Set default computer technology level for newly created users.
155	        $this->setDefaultComputerTechnology();
156	    }
157	
158	    /**
159	     * Create a normal (non-admin) user using the standard Eloquent factories.
160	     */
161	    protected function createUser(): User
162	    {
163	        // Create without model events to skip the `created` hook that promotes the first
164	        // user to admin. That hook issues a cross-row `update users`, which contends with
165	        // the scheduler/queue worker and deadlocks (1205 lock wait) in tests.
166	        $user = User::withoutEvents(fn (): User => User::factory()->create([
167	            'username' => 'test_' . Str::random(16),
168	        ]));
169	
170	        resolve(InitialUserDataService::class)->createFor($user);
171	
172	        return $user;
173	    }
174	
175	    /**
176	     * Set default computer technology level for newly created users.
177	     * Tests that require a different level can override $defaultComputerTechnologyLevel.
178	     */
179	    protected function setDefaultComputerTechnology(): void
180	    {
181	        if ($this->defaultComputerTechnologyLevel === 0) {
182	            // Skip setting if level is 0 (default game behavior).
183	            return;
184	        }
185	
186	        $this->playerSetResearchLevel('computer_technology', $this->defaultComputerTechnologyLevel);
187	    }
188	}

