380	    /** @return list<GameObject> the objects the host itself reports as producing this resource */
381	    private function producersOf(string $resource, PlanetService $planet): array
382	    {
383	        $producers = [];
384	
385	        foreach (ObjectService::getGameObjectsWithProduction() as $object) {
386	            if (!BuildingQueueObject::accepts($object->machine_name)) {
387	                continue;
388	            }
389	
390	            if ($planet->getObjectProduction($object->machine_name, 1, true)->{$resource}->get() <= 0.0) {
391	                continue;
392	            }
393	
394	            $producers[] = $object;
395	        }
396	
397	        return $producers;
398	    }
