418	    /**
419	     * How far this account already is with one prerequisite.
420	     *
421	     * The host keeps a planet's levels on the planet and a technology's on the player, so asking the
422	     * planet for a technology answers zero every time and would offer the same step forever.
423	     */
424	    private function currentLevel(PlanetService $planet, string $machineName): int
425	    {
426	        $isResearch = ObjectService::getObjectByMachineName($machineName)->type === GameObjectType::Research;
427	
428	        if (!$isResearch) {
429	            return $planet->getObjectLevel($machineName);
430	        }
431	
432	        // A planet always has an owner on the host; the nullable signature is the
433	        // host's, so a missing player reads as level zero rather than crashing a
434	        // decision on data the host itself would not normally be without.
435	        return $planet->getPlayer()?->getResearchLevel($machineName) ?? 0;
436	    }
