490	    /** The defence unit the host prices lowest: the smallest thing it will accept as a wall. */
491	    private function smallestDefenceUnit(): ?GameObject
492	    {
493	        $cheapest = null;
494	        $cheapestPrice = INF;
495	
496	        foreach (ObjectService::getDefenseObjects() as $defence) {
497	            $price = ObjectService::getObjectRawPrice($defence->machine_name)->sum();
498	            if ($price <= 0 || $price >= $cheapestPrice) {
499	                continue;
500	            }
501	
502	            $cheapest = $defence;
503	            $cheapestPrice = $price;
504	        }
505	
506	        return $cheapest;
507	    }
508	
509	    /**
510	     * A jump gate moves a fleet between two moons, so it is only ever useful once the account
511	     * owns a pair. The station is not proposed on a single moon (RV-009).
512	     */
513	    private function hasTwoMoons(PlanetService $planet): bool
514	    {
515	        $player = $planet->getPlayer();
516	
517	        return $player !== null && count($player->planets->allMoons()) >= 2;
518	    }
519	
520	    /**
521	     * What this account could produce, cheapest first. An account with no ship that can fly goes for a
522	     * hull before any technology: a player opens with mines, the robotics factory and the shipyard to
523	     * get a first cargo ship, and only then chases research. Without it the cheapest technologies
524	     * come first and the shipyard stays unbuilt, so no fleet, raid or save is ever possible.
525	     *
526	     * @return list<GameObject>
527	     */
528	    private function ambitions(PlanetService $planet): array
529	    {
530	        $objects = [...ObjectService::getResearchObjects(), ...ObjectService::getUnitObjects()];
531	        $player = $planet->getPlayer();
532	        $fleetless = $player !== null && $this->ownsNoMovableShip($player);
533	
534	        // Past the opening the goal is the next war-fleet hull the catalogue prices, because the
535	        // cheapest-first ladder spends the account's whole agenda on everything cheaper while the
536	        // shipyard and the technology a fighting hull waits on stay untouched -- measured live
537	        // 3 Oct 2026: no account in a hundred owned a hull above the median military hull, and the
538	        // surplus bought cargo instead. The hull is never named: it is the cheapest the host groups
539	        // as a military ship that this planet cannot build yet, and its requirements are the host's
540	        // own graph, so a mod-added capital is climbed to with no edit here.
541	        $warHull = $fleetless ? null : $this->warHullPending($planet);
542	
543	        usort(
544	            $objects,
545	            fn (GameObject $left, GameObject $right): int => [
546	                $left->machine_name !== $warHull,
547	                $fleetless && ! $this->isFlyingHull($left, $player),
548	                $left->price->resources->sum(),
549	            ] <=> [
550	                $right->machine_name !== $warHull,
551	                $fleetless && ! $this->isFlyingHull($right, $player),
552	                $right->price->resources->sum(),
553	            ],
554	        );
555	
556	        return $objects;
557	    }
558	
559	    /**
560	     * The cheapest military hull the host's catalogue prices that this planet cannot build yet, or
561	     * null once every one of them is available: the next step of the account's war fleet, ordered by
562	     * the host's own price so a hull a mod adds takes its place in the queue with no edit here.
563	     */
564	    private function warHullPending(PlanetService $planet): ?string
565	    {
566	        $player = $planet->getPlayer();
567	        if ($player === null) {
568	            return null;
569	        }
570	
571	        // Only a hull that shoots grows a war fleet: the catalogue groups a probe or a satellite as a
572	        // military ship, and letting one of them take the ambition spends the climb on a hull that
573	        // fights nothing.
574	        $hulls = array_filter(
575	            ObjectService::getMilitaryShipObjects(),
576	            static fn (UnitObject $hull): bool => $hull->properties->attack->calculate($player)->totalValue > 1,
577	        );
578	        usort($hulls, static fn (GameObject $left, GameObject $right): int =>
579	            $left->price->resources->sum() <=> $right->price->resources->sum());
580	
581	        foreach ($hulls as $hull) {
582	            foreach (ObjectService::getRecursiveRequirements($hull->machine_name) as $machineName => $level) {
583	                if ($this->currentLevel($planet, $machineName) < $level) {
584	                    return $hull->machine_name;
585	                }
586	            }
587	        }
588	
589	        return null;
590	    }
591	
592	    private function ownsNoMovableShip(PlayerService $player): bool
593	    {
594	        foreach ($player->planets->all() as $planet) {
595	            if (MovableFleet::of($player, $planet->getShipUnits())->units !== []) {
596	                return false;
597	            }
598	        }
599	
600	        return true;
601	    }
602	
603	    private function isFlyingHull(GameObject $object, PlayerService|null $player): bool
604	    {
605	        return $object instanceof UnitObject
606	            && $player !== null
607	            && $object->properties->speed->calculate($player)->totalValue > 0;
608	    }
609	}

