 5	use Modules\AI\Models\AiScoreSample;
 6	use OGame\Models\Resources;
 7	use OGame\Services\PlanetService;
 8	
 9	/**
10	 * The per-resource floor a planet must keep after a spend, so one purchase cannot starve the next.
11	 *
12	 * A build that consumes the last metal stops the next save, the next commitment and the next research
13	 * step, so a player reserves first: keep a small fraction of what the planet holds and let the
14	 * production that arrives while saving refill it (SP5). The floor is the buffer reduced by that
15	 * production, and it is never negative. Each resource's floor guards that resource alone, so a planet
16	 * saving deuterium for a drive is not frozen out of spending its surplus metal and crystal: a purchase
17	 * that spends no deuterium must keep no deuterium floor. The buffer, the economy horizon and the
18	 * research horizon are the published defaults the corpus documents; none of them names a game object,
19	 * so nothing here encodes the host's universe.
20	 */
21	class ReserveFloor
22	{
23	    /** Keep this fraction of what the planet holds per resource (SP5, `keep_resources_buffer`). */
24	    public const BUFFER = 0.10;
25	
26	    /** How many hours of production may refill the floor for an economy spend (SP5). */
27	    public const ECONOMY_HOURS = 4.0;
28	
29	    /** How many hours of production may refill the floor for a research spend (SP5). */
30	    public const RESEARCH_HOURS = 6.0;
31	
32	    /** Hourly score samples with no gain at all before the account stops saving and spends (IMPL-69). */
33	    private const STALLED_SAMPLES = 6;
34	
35	    /** @var array<int, bool> */
36	    private array $stalled = [];
37	
38	    /**
39	     * The floor that must survive a purchase, per resource, at this planet.
40	     *
41	     * The buffer is a fraction of the balance, never of the storage capacity. A fresh planet holding
42	     * 529 metal with room for 10,000 has almost nothing to protect, and a reserve charged on capacity
43	     * refuses every purchase it could ever make -- including the mine that earns the reserve back --
44	     * so the account stands still for good. Capping the buffer by the balance keeps the reserve real
45	     * for a rich planet and harmless for a poor one.
46	     *
47	     * @param float $savingHours how long the account is willing to wait for production to refill
48	     */
49	    public function floor(PlanetService $planet, float $savingHours): Resources
50	    {
51	        $held = $planet->getResources();
52	
53	        // An account whose public score has not moved for hours is saving for nothing: the reserve is
54	        // released so the queue spends what is held, which is what a player does on noticing a stall.
55	        if ($this->scoreStalled((int) $planet->getPlayer()?->getId())) {
56	            return new Resources(0.0, 0.0, 0.0);
57	        }
58	
59	        return new Resources(
60	            $this->perResource($held->metal->get(), $planet->getMetalProductionPerHour(), $savingHours),
61	            $this->perResource($held->crystal->get(), $planet->getCrystalProductionPerHour(), $savingHours),
62	            $this->perResource($held->deuterium->get(), $planet->getDeuteriumProductionPerHour(), $savingHours),
63	        );
64	    }
65	
66	    private function perResource(float $held, float $productionPerHour, float $savingHours): float
67	    {
68	        return max(0.0, $held * self::BUFFER - $productionPerHour * $savingHours);
69	    }
70	
71	    private function scoreStalled(int $playerId): bool
72	    {
73	        if ($playerId <= 0) {
74	            return false;
75	        }
76	
77	        return $this->stalled[$playerId] ??= $this->stalledOnSamples($playerId);
78	    }
79	
80	    private function stalledOnSamples(int $playerId): bool
81	    {
82	        $scores = AiScoreSample::query()->where('player_id', $playerId)->orderByDesc('sampled_at')
83	            ->limit(self::STALLED_SAMPLES)->pluck('general');
84	
85	        return $scores->count() === self::STALLED_SAMPLES && $scores->max() === $scores->min();
86	    }
87	}

