333	    private function raidCandidatesFromVisibleReports(PerceptionSnapshot $perception): CandidateGeneration
334	    {
335	        // SP8: no free fleet slot means no raid can be dispatched, so no target is
336	        // offered — the account checks the fleet screen before sending.
337	        if ($perception->fleetSlotsFree < 1) {
338	            return app()->makeWith(CandidateGeneration::class, [
339	                'candidates' => [],
340	                'rejections' => [],
341	            ]);
342	        }
343	
344	        $candidates = [];
345	        $rejections = [];
346	        $farms = [];
347	
348	        // Raid candidates are assembled solely from the published report
349	        // projection. The scorer never receives unseen defender information.
350	        foreach ($perception->targetReports as $report) {
351	            $reportKey = 'report:' . $report['report_id'];
352	            if (!$report['attack_permitted']) {
353	                $rejections[$reportKey] = AiCandidateRejectionReason::AttackNotPermitted->value;
354	                continue;
355	            }
356	
357	            if ($report['expires_at'] <= $perception->observedAt->getTimestamp()) {
358	                $rejections[$reportKey] = AiCandidateRejectionReason::StaleTargetIntel->value;
359	                continue;
360	            }
361	
362	            // A target scoring under ~⅕ of ours cannot defend its loot, so it is
363	            // dropped before the estimator runs (RAID-008). Fixtures built
364	            // without the field stay viable rather than silently disappearing.
365	            if (!($report['score_viable'] ?? true)) {
366	                $rejections[$reportKey] = AiCandidateRejectionReason::ScoreBelowViability->value;
367	                continue;
368	            }
369	
370	            // The raid planner is the only authority on whether this raid can be carried out at
371	            // all: it applies the bashing limit, the fleet's own capacity and the profit estimate,
372	            // and none of those travel in the report projection. Offering a target the planner will
373	            // decline is how the population came to decide without ever acting -- measured on the
374	            // grand test at 154 of 181 raid selections producing no work item at all, a third of
375	            // every decision made. Asking here keeps the candidate list to raids that will actually
376	            // be queued, and the drop is recorded so the trace can show it rather than hide it.
377	            if (!$this->raidPlanner->plan($perception->playerId, (int) $report['report_id']) instanceof QueueableRaid) {
378	                $rejections[$reportKey] = AiCandidateRejectionReason::RaidNotViable->value;
379	                continue;
380	            }
381	
382	            if ($report['defenceless'] ?? false) {
383	                $farms[] = $reportKey;
384	            }
385	
386	            $candidates[] = app()->makeWith(CandidateAction::class, [
387	                'type' => AiCandidateActionType::Raid,
388	                'reason' => AiCandidateReason::FreshVisibleReport->value,
389	                'parameters' => ['report_id' => $report['report_id']],
390	                'features' => $this->features(AiCandidateActionType::Raid, 0, $report['confidence'], $report['travel_cost'], $perception->recoveryFactor),
391	                'sourceTimestamps' => [AiCandidateReason::reportSource($report['report_id']) => date(DATE_ATOM, $report['observed_at'])],
392	            ]);
393	        }
394	
395	        // A day of raids that only pillage empty planets has no combat, no debris and no moons, which an
396	        // administrator reads as a dead universe (LIFE_FIGHTS). When a defended target also clears the
397	        // planner, the empty farm waits: the fight is the better play and the farm stays for the sessions
398	        // that have nothing defended to hit.
399	        if ($farms !== [] && count($farms) < count($candidates)) {
400	            $candidates = array_values(array_filter(
401	                $candidates,
402	                static function (CandidateAction $candidate) use ($farms, &$rejections): bool {
403	                    $key = 'report:' . ($candidate->parameters['report_id'] ?? '');
404	                    if (!in_array($key, $farms, true)) {
405	                        return true;
406	                    }
407	                    $rejections[$key] = AiCandidateRejectionReason::DefendedTargetPreferred->value;
408	
409	                    return false;
410	                },
411	            ));
412	        }
413	
414	        return app()->makeWith(CandidateGeneration::class, [
415	            'candidates' => $candidates,
416	            'rejections' => $rejections,
417	        ]);
418	    }
