  428	    /** Runs one manager's schedule call under its own key; true when it wrote an order. */
  429	    private function asManager(string $suffix, \Closure $schedule): bool
  430	    {
  431	        $this->managerSuffix = $suffix;
  432	        $this->enqueued = false;
  433	
  434	        try {
  435	            $schedule();
  436	        } finally {
  437	            $this->managerSuffix = '';
  438	        }
  439	
  440	        return $this->enqueued;
  441	    }
