16	 * Runs one session work item.
17	 *
18	 * The conversation cycle is composed here, where the session's own work is composed,
19	 * rather than inside the scheduling service: the session answers what is pending and then
20	 * decides what to do, and the scheduling service keeps depending on nothing but its own
21	 * domain.
22	 */
23	class RunAiSessionAction implements RunAiSession
24	{
25	    public function __construct(
26	        private SessionDecisionService $sessionDecisionService,
27	        private ScheduleAiIntentAction $scheduleAiIntentAction,
28	        private AiClock $clock,
29	        private PlayerGameStateService $playerGameStateService,
30	    ) {
31	    }
32	
33	    public function handle(AiProfile $profile, AiWorkItem $workItem): void
34	    {
35	        // Scheduled actors have no HTTP page load to advance completed host queues. Use the host
36	        // seam without stamping activity when the session later decides to do nothing.
37	        if (User::query()->whereKey($profile->player_id)->exists()) {
38	            $player = $this->playerGameStateService->advance($profile->player_id, null, false);
39	
40	            // advance() drains the queues of the player's current planet alone; every other planet
41	            // is advanced only on a page visit that never happens for a scheduled actor. A colony the
42	            // account settles therefore fills its five queue slots and stays full forever, so it never
43	            // builds a shipyard, a ship or a defence. Drain each remaining planet the same way the
44	            // host's own page load does.
45	            if ($player->planets->all() !== []) {
46	                $currentPlanetId = $player->planets->current()->getPlanetId();
47	
48	                foreach ($player->planets->all() as $planet) {
49	                    if ($planet->getPlanetId() === $currentPlanetId) {
50	                        continue;
51	                    }
52	
53	                    $planet->update();
54	                }
55	            }
56	        }
57	
58	        // A message is answered when the account next wakes, not when it next thinks about
59	        // its economy: sessions are 34 to 56 minutes apart, and that is the whole window a
60	        // reply has to fit inside.
61	        if (app(AiRuntimeSettings::class)->conversationEnabled()) {
62	            app(RunAiConversationCycleAction::class)->handle($profile->player_id, $this->clock->now());
63	        }
64	
65	        // The host scheduler misses cron-minute events (HARNESS-003), so the alliance lane would never
66	        // run; the first session each minute runs it, which is the cadence the schedule promises (ALLY-001).
67	        if (Cache::add('ai:alliance-life:minute', true, 60)) {
68	            app(AdvanceAiAllianceLifeAction::class)->handle();
69	        }
70	
71	        // The decision is recorded first and the intent scheduled from what it recorded, so a
72	        // session whose choice cannot be carried out still leaves the trace of what it wanted.
73	        $trace = $this->sessionDecisionService->run($profile, $workItem);
74	        $this->scheduleAiIntentAction->handle($profile, $workItem, $trace);
75	    }
76	}

