 27	/**
 28	 * Records a deterministic session decision and schedules exactly one future
 29	 * session. Action execution is deliberately outside this service: unavailable
 30	 * capabilities remain traceable intents rather than requiring AI-specific host
 31	 * contracts.
 32	 */
 33	class SessionDecisionService
 34	{
 35	    private const TRACE_RETENTION_DAYS = 30;
 36	
 37	    /** SP3: the account arrives this many seconds after a material event, right-skewed toward short. */
 38	    private const MATERIAL_EVENT_ARRIVAL_MIN_SECONDS = 30;
 39	
 40	    private const MATERIAL_EVENT_ARRIVAL_MAX_SECONDS = 300;
 41	
 42	    public function __construct(
 43	        private PlayerPerceptionBuilder $playerPerceptionBuilder,
 44	        private SessionPlanner $sessionPlanner,
 45	        private NextDueTimeCalculator $nextDueTimeCalculator,
 46	        private DecisionEngine $decisionEngine,
 47	        private ConsultCampaignDecisionAction $consultCampaignDecision,
 48	        private AiClock $clock,
 49	        private AccountStateResolver $accountStateResolver,
 50	        private RandomSource $randomSource,
 51	    ) {
 52	    }
 53	
 54	    public function run(AiProfile $profile, AiWorkItem $workItem): DecisionTrace
 55	    {
 56	        $now = $this->clock->now();
 57	        $routine = RoutineProfile::fromAiProfile($profile);
 58	        $schedule = $this->scheduleFor($profile, $routine, $now);
 59	
 60	        // The session plan is computed before the decision so the decision can
 61	        // see the absence this session is about to enter (V6): a proactive save
 62	        // is offered only when the gap until the next session is a real one.
 63	        $plan = $this->sessionPlanner->plan($profile, $now, $schedule->generation);
 64	        // Carbon 3 signs its differences: measured from the session's end forward to the next login, the gap is positive.
 65	        // The login that really comes next, not the routine's: an accelerated universe is back in seconds,
 66	        // and a save before an absence that never happens only parks a fleet that should be fighting.
 67	        $upcomingAbsenceMinutes = max(0, (int) $plan->sessionEndsAt->diffInMinutes($this->nextDueTimeCalculator->fromSession($plan, $now)));
 68	
 69	        $perception = $this->playerPerceptionBuilder->build($profile->player_id, $upcomingAbsenceMinutes);
 70	        $decisionKey = 'work:' . $workItem->id . ':generation:' . $schedule->generation;
 71	        $trace = $this->decisionEngine->decide($profile, $perception, $decisionKey);
 72	
 73	        // A material campaign event (a new phase, a held stronghold) consults once here and may
 74	        // nudge the ranking before the final selection; off by default, so an ordinary session
 75	        // makes no provider call and its recorded decision is unchanged.
 76	        $trace = $this->consultCampaignDecision->handle($profile, $trace, $decisionKey);
 77	
 78	        $this->recordDecisionTrace($profile, $workItem, $trace, $now);
 79	
 80	        // An account with no planets, or one the host no longer has, has nothing
 81	        // to come back to. The session still records what it decided, and the
 82	        // chain stops instead of deciding nothing forever -- and stopping it is
 83	        // the whole difference between an idle account and a stated one.
 84	        if (!$this->accountStateResolver->resolve($profile->player_id)->schedules()) {
 85	            return $trace;
 86	        }
 87	
 88	        $nextDueAt = $this->nextDueTimeCalculator->fromSession($plan, $now);
 89	
 90	        // An accelerated universe still sleeps: a session that would land in the dark period waits
 91	        // for the routine's wake, or every account reads as round-the-clock (AUTH_UPTIME).
 92	        if (!$this->sessionPlanner->isAwake($profile, $nextDueAt)) {
 93	            $nextDueAt = $plan->nextDueAt;
 94	        }
 95	
 96	        // V2: a hostile inbound schedules the reaction wake, so the account reacts inside the
 97	        // window before impact instead of at its next ordinary session.
 98	        if ($perception->reactionWakeAt !== null) {
 99	            $reactionWakeAt = CarbonImmutable::createFromTimestamp($perception->reactionWakeAt);
100	            if ($reactionWakeAt->greaterThan($now) && $reactionWakeAt->lessThan($nextDueAt) && $this->wakesForReaction($profile, $reactionWakeAt)) {
101	                $nextDueAt = $reactionWakeAt;
102	            }
103	        }
104	
105	        // SP3: wake at the next material event inside the waking window (a build, research or
106	        // fleet landing) instead of the full routine gap; the routine session stays the bound.
107	        $nextDueAt = $this->nextMaterialEventWake($profile, $perception, $now, $nextDueAt);
108	
109	        // An account that sleeps still lives: a session is never scheduled past the host's own
110	        // inactive-deletion threshold, so a long persona-shaped absence reads as a holiday,
111	        // never as an abandoned account the host would purge.
112	        $nextDueAt = $this->livenessFloor($now, $nextDueAt);
113	
114	        $nextGeneration = $schedule->generation + 1;
115	
116	        $this->scheduleSuccessor($profile, $routine, $schedule, $plan->sessionEndsAt, $nextDueAt, $nextGeneration, $now);
117	
118	        return $trace;
119	    }
120	
121	    /**
122	     * Whether a hostile inbound brings the account back before its next ordinary session.
123	     *
124	     * A player at the keyboard answers an attack coming in; one who is asleep reads the report with the
125	     * next morning's coffee. The look therefore only counts inside the account's own waking window: a
126	     * session taken in the dark period is a login the account never makes, and the host counts the
127	     * hours of the day an account is active (AUTH_UPTIME) -- the routine already spans most of them, so
128	     * a single session in the night is the whole difference between a player and a machine. The attack
129	     * is read at the next waking session instead.
130	     */
131	    private function wakesForReaction(AiProfile $profile, CarbonImmutable $wakeAt): bool
132	    {
133	        return $this->sessionPlanner->isAwake($profile, $wakeAt);
134	    }
135	
136	    private function scheduleFor(AiProfile $profile, RoutineProfile $routine, CarbonImmutable $now): AiSchedule
137	    {
138	        return AiSchedule::query()->firstOrCreate(
139	            ['player_id' => $profile->player_id],
140	            ['timezone' => $routine->timezone, 'next_due_at' => $now, 'generation' => 1],
141	        );
142	    }
143	
144	    /**
145	     * The first material event the account would be awake for, or the routine next-due when
146	     * every event lands in the dark period. Each candidate is the host's own finish/arrival
147	     * time plus a right-skewed arrival delay, so the account checks shortly after the event
148	     * rather than sitting on it exactly (SP3).
149	     */
150	    private function nextMaterialEventWake(AiProfile $profile, PerceptionSnapshot $perception, CarbonImmutable $now, CarbonImmutable $routineNextDue): CarbonImmutable
151	    {
152	        $next = $routineNextDue;
153	        $seed = $profile->random_seed;
154	
155	        foreach ($this->materialEventEtas($profile, $perception, $now) as $eta) {
156	            $candidate = CarbonImmutable::createFromTimestamp($eta)
157	                ->addSeconds($this->materialArrivalDelay($seed, (string) $eta));
158	
159	            if ($candidate->greaterThan($now) && $candidate->lessThan($next) && $this->sessionPlanner->isAwake($profile, $candidate)) {
160	                $next = $candidate;
161	            }
162	        }
163	
164	        return $next;
165	    }
166	
167	    /** @return list<int> */
168	    private function materialEventEtas(AiProfile $profile, PerceptionSnapshot $perception, CarbonImmutable $now): array
169	    {
170	        $nowTimestamp = $now->getTimestamp();
171	        $planetIds = array_column($perception->planets, 'id');
172	        $etas = [];
173	
174	        if ($planetIds !== []) {
175	            $buildingFinish = BuildingQueue::query()
176	                ->whereIn('planet_id', $planetIds)
177	                ->where('processed', 0)
178	                ->where('time_end', '>', $nowTimestamp)
179	                ->min('time_end');
180	
181	            if ($buildingFinish !== null) {
182	                $etas[] = (int) $buildingFinish;
183	            }
184	
185	            $researchFinish = ResearchQueue::query()
186	                ->whereIn('planet_id', $planetIds)
187	                ->where('processed', 0)
188	                ->where('time_end', '>', $nowTimestamp)
189	                ->min('time_end');
190	
191	            if ($researchFinish !== null) {
192	                $etas[] = (int) $researchFinish;
193	            }
194	        }
195	
196	        $fleetArrival = FleetMission::query()
197	            ->where('user_id', $profile->player_id)
198	            ->where('processed', 0)
199	            ->where('canceled', 0)
200	            ->where('time_arrival', '>', $nowTimestamp)
201	            ->min('time_arrival');
202	
203	        if ($fleetArrival !== null) {
204	            $etas[] = (int) $fleetArrival;
205	        }
206	
207	        foreach ($perception->inboundFleets as $inbound) {
208	            $etas[] = (int) $inbound['time_arrival'];
209	        }
210	
211	        return $etas;
212	    }
213	
214	    /**
215	     * The seconds the account arrives after a material event: right-skewed (squared), so it
216	     * mostly checks shortly after the event and occasionally much later (SP3 jitter).
217	     */
218	    private function materialArrivalDelay(int $seed, string $eventKey): int
219	    {
220	        $unit = $this->randomSource->unitInterval($seed, 'sp3:arrival:' . $eventKey);
221	
222	        return self::MATERIAL_EVENT_ARRIVAL_MIN_SECONDS
223	            + (int) round((self::MATERIAL_EVENT_ARRIVAL_MAX_SECONDS - self::MATERIAL_EVENT_ARRIVAL_MIN_SECONDS) * $unit * $unit);
224	    }
225	
226	    /**
227	     * Caps the next session at one day before the host would delete an inactive
228	     * account, read from the host's own setting. Zero (the default) disables the
229	     * clamp, so the persona's holiday cadence is unchanged unless the operator
230	     * has actually enabled inactive-player deletion.
231	     */
232	    private function livenessFloor(CarbonImmutable $now, CarbonImmutable $nextDueAt): CarbonImmutable
233	    {
234	        $deletionDays = app(SettingsService::class)->inactivePlayerDeletionDays();
235	        if ($deletionDays <= 1) {
236	            return $nextDueAt;
237	        }
238	
239	        $floor = $now->addDays($deletionDays - 1);
240	
241	        return $nextDueAt->lessThan($floor) ? $nextDueAt : $floor;
242	    }
243	
244	    private function recordDecisionTrace(AiProfile $profile, AiWorkItem $workItem, DecisionTrace $trace, CarbonImmutable $now): void
245	    {
246	        AiDecisionTrace::query()->create([
247	            'player_id' => $profile->player_id,
248	            'work_item_id' => $workItem->id,
249	            ...$trace->record(),
250	            'expires_at' => $now->addDays(self::TRACE_RETENTION_DAYS),
251	        ]);
252	    }
253	
254	    private function scheduleSuccessor(AiProfile $profile, RoutineProfile $routine, AiSchedule $schedule, CarbonImmutable $sessionEndsAt, CarbonImmutable $nextDueAt, int $nextGeneration, CarbonImmutable $now): void
255	    {
256	        $schedule->update([
257	            'timezone' => $routine->timezone,
258	            'next_due_at' => $nextDueAt,
259	            'session_ends_at' => $sessionEndsAt,
260	            'generation' => $nextGeneration,
261	            'last_activity_at' => $now,
262	        ]);
263	        // Generation is part of the idempotency key: retries of this session
264	        // converge on one successor, while a later session gets new work.
265	        AiWorkItem::query()->firstOrCreate(
266	            ['idempotency_key' => 'session:' . $profile->player_id . ':' . $nextGeneration],
267	            [
268	                'player_id' => $profile->player_id,
269	                'kind' => AiWorkKind::RunSession,
270	                'due_at' => $nextDueAt,
271	                'schedule_generation' => $nextGeneration,
272	                'state' => AiWorkState::Pending,
273	            ],
274	        );
275	    }
276	}

